<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { Paperclip, X } from '@lucide/vue'
import { db } from '../../db'
import { studentService } from '../../services/studentService'
import { useCommunicationStore } from '../../stores/useCommunicationStore'
import { useTermStore } from '../../stores/useTermStore'
import type { CommunicationAttachment, CommunicationLog, Student } from '../../types/schema'

const props = defineProps<{ editingId?: string | null; initialStudentId?: string | null }>(); const emit = defineEmits<{ saved: [] }>()
const store = useCommunicationStore(); const termStore = useTermStore(); const students = ref<Student[]>([]); const saving = ref(false)
const nowLocal = () => new Date(Date.now() - new Date().getTimezoneOffset() * 60000).toISOString().slice(0, 16)
const form = reactive({ studentId: props.initialStudentId ?? '', targetType: 'parent' as CommunicationLog['targetType'], targetName: '', communicationMode: 'phone' as CommunicationLog['communicationMode'], dateTime: nowLocal(), summary: '', actionPlan: '', attachments: [] as CommunicationAttachment[] })
const selectedStudent = computed(() => students.value.find((item) => item.id === form.studentId))
function normalizeDateTime(value: string) { return value.replace('T', ' ').slice(0, 16) }
async function fileToAttachment(file: File) { const url = await new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result)); reader.onerror = reject; reader.readAsDataURL(file) }); const type: CommunicationAttachment['type'] = file.type.startsWith('image/') ? 'image' : file.type.startsWith('audio/') ? 'audio' : file.type.startsWith('video/') ? 'video' : 'file'; return { id: crypto.randomUUID(), name: file.name, type, url, size: `${Math.max(1, Math.round(file.size / 1024))} KB` } }
async function addFiles(files: FileList | File[]) { form.attachments.push(...await Promise.all([...files].map(fileToAttachment))) }
function serializeAttachments() { return form.attachments.map(({ id, name, type, url, size }) => ({ id, name, type, url, size })) }
async function save() { if (!form.studentId || !termStore.currentTermId || !form.targetName.trim() || !form.summary.trim()) return; saving.value = true; try { const draft = { studentId: form.studentId, studentName: selectedStudent.value?.name ?? '', termId: termStore.currentTermId, targetType: form.targetType, targetName: form.targetName.trim(), communicationMode: form.communicationMode, dateTime: normalizeDateTime(form.dateTime), summary: form.summary.trim(), actionPlan: form.actionPlan.trim(), attachments: serializeAttachments() }; if (props.editingId) await store.updateLog(props.editingId, draft); else await store.addLog(draft); emit('saved'); store.closeForm() } finally { saving.value = false } }
onMounted(async () => { students.value = await studentService.list(); if (props.editingId) { const log = await db.communicationLogs.get(props.editingId); if (log) Object.assign(form, { ...log, dateTime: log.dateTime.replace(' ', 'T') }) } })
</script>
<template><Teleport to="body"><div class="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/35 p-4" @click.self="store.closeForm()"><section class="max-h-[92vh] w-full max-w-2xl overflow-y-auto rounded-2xl bg-white p-6 shadow-2xl"><header class="flex items-center justify-between"><h2 class="text-lg font-semibold text-slate-800">{{ editingId ? '编辑沟通记录' : '新增沟通记录' }}</h2><button type="button" class="rounded p-1 text-slate-400 hover:bg-slate-100" @click="store.closeForm()"><X :size="18" /></button></header><div class="mt-5 grid gap-4 sm:grid-cols-2"><label class="text-sm font-medium text-slate-700">学生<select v-model="form.studentId" class="mt-1.5 w-full rounded-lg border border-slate-200 px-3 py-2"><option value="">请选择学生</option><option v-for="student in students" :key="student.id" :value="student.id">{{ student.name }} · {{ student.studentNo }}</option></select></label><label class="text-sm font-medium text-slate-700">沟通时间<input v-model="form.dateTime" type="datetime-local" class="mt-1.5 w-full rounded-lg border border-slate-200 px-3 py-2" /></label><fieldset class="sm:col-span-2"><legend class="text-sm font-medium text-slate-700">沟通对象</legend><div class="mt-2 flex flex-wrap gap-2"><label v-for="item in [['parent','家长'],['teacher','班主任'],['leader','学校领导'],['other','其他']]" :key="item[0]" class="rounded-full border px-3 py-1.5 text-sm" :class="form.targetType === item[0] ? 'border-emerald-300 bg-emerald-50 text-emerald-800' : 'border-slate-200 text-slate-600'"><input v-model="form.targetType" class="sr-only" type="radio" :value="item[0]" />{{ item[1] }}</label></div></fieldset><label class="text-sm font-medium text-slate-700">具体对象<input v-model="form.targetName" class="mt-1.5 w-full rounded-lg border border-slate-200 px-3 py-2" placeholder="如：张妈妈" /></label><label class="text-sm font-medium text-slate-700">沟通形式<select v-model="form.communicationMode" class="mt-1.5 w-full rounded-lg border border-slate-200 px-3 py-2"><option value="phone">电话</option><option value="wechat">微信</option><option value="in_person">面对面</option><option value="meeting">专题会议</option></select></label></div><label class="mt-4 block text-sm font-medium text-slate-700">沟通要点<textarea v-model="form.summary" rows="4" class="mt-1.5 w-full rounded-lg border border-slate-200 p-3" /></label><label class="mt-4 block text-sm font-medium text-slate-700">后续约定<textarea v-model="form.actionPlan" rows="3" class="mt-1.5 w-full rounded-lg border border-slate-200 p-3" /></label><div class="mt-4 rounded-xl border border-dashed border-slate-300 p-3"><label class="inline-flex cursor-pointer items-center gap-2 text-sm font-medium text-emerald-700"><Paperclip :size="16" />添加附件<input class="hidden" type="file" multiple accept="image/*,audio/*,video/*,.pdf,.doc,.docx" @change="addFiles(($event.target as HTMLInputElement).files!)" /></label><div v-if="form.attachments.length" class="mt-3 flex flex-wrap gap-2"><span v-for="file in form.attachments" :key="file.id" class="inline-flex items-center gap-1 rounded bg-slate-100 px-2 py-1 text-xs text-slate-600">{{ file.name }}<button type="button" class="text-rose-500" @click="form.attachments = form.attachments.filter((item) => item.id !== file.id)">×</button></span></div></div><footer class="mt-6 flex justify-end gap-2"><button type="button" class="rounded-lg px-3 py-2 text-sm text-slate-600" @click="store.closeForm()">取消</button><button type="button" :disabled="saving" class="rounded-lg bg-emerald-600 px-4 py-2 text-sm font-semibold text-white disabled:opacity-50" @click="save">{{ saving ? '保存中…' : '保存记录' }}</button></footer></section></div></Teleport></template>
